create table public.resumes (id uuid primary key default uuid_generate_v4(), student_id uuid references public.student_profiles(id) on delete cascade, storage_path text not null, original_filename text not null, parsed_text text, parsed_skills jsonb default '{}', created_at timestamptz default now());
create table public.certifications (id uuid primary key default uuid_generate_v4(), student_id uuid references public.student_profiles(id) on delete cascade, name text not null, issuer text, credential_url text, created_at timestamptz default now());
create table public.experiences (id uuid primary key default uuid_generate_v4(), student_id uuid references public.student_profiles(id) on delete cascade, kind text not null, title text not null, organization text, description text, started_at date, ended_at date);
create table public.career_role_matches (student_id uuid references public.student_profiles(id) on delete cascade, role_id uuid references public.roles(id) on delete cascade, match_score numeric(5,2), strengths jsonb default '[]', gaps jsonb default '[]', calculated_at timestamptz default now(), primary key(student_id,role_id));
create table public.student_skill_gaps (student_id uuid references public.student_profiles(id) on delete cascade, skill_id uuid references public.skills(id) on delete cascade, current_level numeric(5,2), required_level numeric(5,2), importance text, estimated_hours int, primary key(student_id,skill_id));
create table public.student_job_matches (student_id uuid references public.student_profiles(id) on delete cascade, job_id uuid references public.jobs(id) on delete cascade, match_score numeric(5,2), matched_skills jsonb default '[]', missing_skills jsonb default '[]', calculated_at timestamptz default now(), primary key(student_id,job_id));
create table public.placement_results (id uuid primary key default uuid_generate_v4(), application_id uuid references public.applications(id) on delete cascade, outcome text not null check(outcome in ('Selected','Rejected')), source text default 'company_csv', created_at timestamptz default now());
create table public.institutional_metrics (id uuid primary key default uuid_generate_v4(), metric_date date not null default current_date, metric_name text not null, metric_value numeric, metadata jsonb default '{}');
create table public.skill_gap_snapshots (id uuid primary key default uuid_generate_v4(), captured_at timestamptz default now(), department text, cohort text, skill_id uuid references public.skills(id), average_proficiency numeric(5,2), market_demand numeric(5,2));
create table public.bootcamp_enrollments (bootcamp_id uuid references public.bootcamps(id) on delete cascade, student_id uuid references public.student_profiles(id) on delete cascade, status text default 'invited', enrolled_at timestamptz default now(), primary key(bootcamp_id,student_id));
create index resumes_student_idx on public.resumes(student_id); create index results_application_idx on public.placement_results(application_id); create index metrics_name_date_idx on public.institutional_metrics(metric_name,metric_date);
